/** Chain-verbatim mock set for an incident block. */
export function incidentMocks(block: IncidentBlock): RawMock[] {
  if (block === 26004768) return BLOCK_26004768.map((m) => ({ ...m }))
  if (block === 26004793) return BLOCK_26004793.map((m) => ({ ...m }))
  return BLOCK_26004820.map((m) => ({ ...m }))
}
